-- Payments V8 safety runtime: signed schedule reconciliation, manifests, retries and convergence watchdog.

create or replace function portal_private.reconcile_finance_authority_from_signed_schedule_v8(p_basis_authority_id uuid)
returns jsonb language plpgsql security definer set search_path to 'pg_catalog','portal_private' as $function$
declare b portal_private.deal_finance_authority_v7%rowtype; v_group uuid; v_doc_key uuid; v_doc_ver uuid; v_doc_id text; v_version text; v_currency text; v_plan_total numeric:=0; v_received numeric:=0; v_left numeric:=0; v_due numeric:=0; v_expected numeric:=0; v_cond numeric:=0; r portal_private.owner_payment_plan%rowtype; v_rem numeric; v_id uuid:=gen_random_uuid(); v_idem text; v_refs jsonb; v_status text; v_doc_status text; v_existing uuid;
begin
  select * into b from portal_private.deal_finance_authority_v7 where id=p_basis_authority_id; if not found then return jsonb_build_object('accepted',false,'reason_code','BASIS_AUTHORITY_NOT_FOUND'); end if;
  if coalesce(b.source_version,'') like 'FINANCE_SIGNED_SCHEDULE_V8:%' then return jsonb_build_object('accepted',true,'materialized',false,'reason_code','V8_AUTHORITY_ALREADY_CANONICAL'); end if;
  select p.schedule_group_id,p.source_document_key,p.source_document_version_key,p.schedule_version,upper(btrim(p.currency::text)),sum(p.planned_amount) into v_group,v_doc_key,v_doc_ver,v_version,v_currency,v_plan_total from portal_private.owner_payment_plan p where p.deal_key=b.deal_key and p.schedule_authority_state='CONFIRMED' and p.status<>'CANCELLED' and p.source_system='FINANCE_SIGNED_DOCUMENT_PAYMENT_SCHEDULE_V8' group by p.schedule_group_id,p.source_document_key,p.source_document_version_key,p.schedule_version,upper(btrim(p.currency::text)) order by max(p.materialized_at) desc nulls last limit 1;
  if v_group is null then return jsonb_build_object('accepted',true,'materialized',false,'reason_code','NO_V8_SCHEDULE'); end if;
  select d.document_id into v_doc_id from portal_private.documents d join portal_private.document_versions dv on dv.id=d.current_version_id where d.id=v_doc_key and dv.id=v_doc_ver and d.deal_key=b.deal_key and upper(d.document_type) in ('SIGNED_ADDENDUM','SIGNED_SPECIFICATION','SIGNED_CONTRACT') and upper(d.authority_state::text)='CONFIRMED' and upper(d.lifecycle_state::text)='ACTIVE' and dv.is_current=true and dv.is_effective=true and upper(dv.authority_state::text)='CONFIRMED' and upper(dv.lifecycle_state::text)='ACTIVE';
  if v_doc_id is null then insert into portal_private.finance_schedule_integrity_alerts_v8(deal_key,basis_authority_id,schedule_group_id,source_document_version_key,reason_code,details) values(b.deal_key,b.id,v_group,v_doc_ver,'V8_SCHEDULE_SOURCE_DOCUMENT_STALE',jsonb_build_object('basis_authority_id',b.id,'schedule_version',v_version)) on conflict(deal_key,reason_code) where status='OPEN' do update set basis_authority_id=excluded.basis_authority_id,details=excluded.details,created_at=clock_timestamp(); return jsonb_build_object('accepted',false,'materialized',false,'reason_code','V8_SCHEDULE_SOURCE_DOCUMENT_STALE'); end if;
  if upper(btrim(b.obligation_currency::text))<>v_currency or abs(b.total_to_receive-v_plan_total)>0.01 then insert into portal_private.finance_schedule_integrity_alerts_v8(deal_key,basis_authority_id,schedule_group_id,source_document_version_key,reason_code,details) values(b.deal_key,b.id,v_group,v_doc_ver,'FINANCE_AUTHORITY_SIGNED_SCHEDULE_MISMATCH',jsonb_build_object('basis_total',b.total_to_receive,'basis_currency',btrim(b.obligation_currency::text),'schedule_total',v_plan_total,'schedule_currency',v_currency,'source_document_id',v_doc_id)) on conflict(deal_key,reason_code) where status='OPEN' do update set basis_authority_id=excluded.basis_authority_id,details=excluded.details,created_at=clock_timestamp(); return jsonb_build_object('accepted',false,'materialized',false,'reason_code','FINANCE_AUTHORITY_SIGNED_SCHEDULE_MISMATCH'); end if;
  v_received:=b.total_to_receive-(b.due_now+b.expected_not_due+b.future_conditional); if v_received< -0.01 or v_received>v_plan_total+0.01 then return jsonb_build_object('accepted',false,'materialized',false,'reason_code','RECOGNIZED_RECEIPT_INVALID'); end if; v_received:=greatest(0,v_received); v_left:=v_received;
  for r in select * from portal_private.owner_payment_plan where deal_key=b.deal_key and schedule_group_id=v_group and schedule_authority_state='CONFIRMED' and status<>'CANCELLED' order by tranche_no loop v_rem:=greatest(0,r.planned_amount-least(r.planned_amount,v_left)); v_left:=greatest(0,v_left-r.planned_amount); if v_rem>0 then if r.due_state='CURRENT_DUE' then v_due:=v_due+v_rem; elsif r.due_state='DEFERRED_NOT_DUE' and nullif(btrim(coalesce(r.trigger_type,'')),'') is not null and r.trigger_state='NOT_CONFIRMED' then v_cond:=v_cond+v_rem; elsif r.due_state='DEFERRED_NOT_DUE' then v_expected:=v_expected+v_rem; end if; end if; end loop;
  if abs((v_due+v_expected+v_cond)-(v_plan_total-v_received))>0.01 then return jsonb_build_object('accepted',false,'materialized',false,'reason_code','V8_RECONCILIATION_BUCKET_INTEGRITY_ERROR'); end if;
  if abs(b.due_now-v_due)<=0.01 and abs(b.expected_not_due-v_expected)<=0.01 and abs(b.future_conditional-v_cond)<=0.01 then update portal_private.finance_schedule_integrity_alerts_v8 set status='RESOLVED',resolved_at=clock_timestamp() where deal_key=b.deal_key and status='OPEN' and reason_code in ('FINANCE_AUTHORITY_SIGNED_SCHEDULE_MISMATCH','V8_BUCKET_REGRESSION'); return jsonb_build_object('accepted',true,'materialized',false,'reason_code','BASIS_ALREADY_MATCHES_V8','recognized_received',v_received,'remaining_to_receive',v_plan_total-v_received); end if;
  v_idem:='signed-schedule-reconcile-v8:'||b.id::text; select id into v_existing from portal_private.deal_finance_authority_v7 where deal_key=b.deal_key and idempotency_key=v_idem limit 1; if v_existing is not null then return jsonb_build_object('accepted',true,'materialized',false,'idempotent_replay',true,'authority_id',v_existing); end if;
  v_status:=case when v_plan_total-v_received<=0.01 then 'PAID' when v_received>0 then 'PARTIAL' when v_due>0 then 'DUE' else 'NOT_DUE' end; v_doc_status:=b.documentary_status; if v_cond>0 and upper(coalesce(v_doc_status,'')) not like 'BANK_%' then v_doc_status:='TO_VERIFY'; end if;
  v_refs:=coalesce(b.source_refs,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('source_type','FINANCE_AUTHORITY','source_id',b.id::text),jsonb_build_object('source_type','PAYMENT_SCHEDULE','source_id',v_group::text),jsonb_build_object('source_type','DOCUMENT','source_id',v_doc_id),jsonb_build_object('source_type','DOCUMENT_VERSION','source_id',v_doc_ver::text));
  insert into portal_private.deal_finance_authority_v7(id,deal_key,total_to_receive,due_now,expected_not_due,future_conditional,obligation_currency,contractual_payment_currency,mixed_inbound_accounting_currency,finance_status,documentary_status,authority_state,lifecycle_state,effective_at,supersedes_id,supersedes_authority_refs,source_version,source_timestamp,source_refs,source_locked,actor_id,actor_role,correlation_id,idempotency_key,actual_spend,actual_spend_status,remaining_execution,remaining_execution_status,execution_currency,execution_status) values(v_id,b.deal_key,v_plan_total,v_due,v_expected,v_cond,v_currency::char(3),coalesce(b.contractual_payment_currency,v_currency::char(3)),b.mixed_inbound_accounting_currency,v_status,v_doc_status,'AUTHORITATIVE','CURRENT',clock_timestamp(),b.id,jsonb_build_array(jsonb_build_object('source_type','FINANCE_AUTHORITY','source_id',b.id::text)),'FINANCE_SIGNED_SCHEDULE_V8:RECONCILE:'||coalesce(v_version,'UNVERSIONED'),b.source_timestamp,v_refs,true,'AI-FINANCE','FINANCE',coalesce(b.correlation_id,gen_random_uuid()),v_idem,b.actual_spend,b.actual_spend_status,b.remaining_execution,b.remaining_execution_status,b.execution_currency,b.execution_status);
  insert into portal_private.finance_schedule_integrity_alerts_v8(deal_key,basis_authority_id,schedule_group_id,source_document_version_key,reason_code,details,status,resolved_at) values(b.deal_key,b.id,v_group,v_doc_ver,'V8_BUCKET_REGRESSION',jsonb_build_object('basis_due',b.due_now,'basis_expected',b.expected_not_due,'basis_conditional',b.future_conditional,'corrected_due',v_due,'corrected_expected',v_expected,'corrected_conditional',v_cond,'recognized_received',v_received),'RESOLVED',clock_timestamp()) on conflict(deal_key,reason_code) where status='OPEN' do update set status='RESOLVED',resolved_at=clock_timestamp(),details=excluded.details;
  return jsonb_build_object('accepted',true,'materialized',true,'authority_id',v_id,'supersedes_id',b.id,'recognized_received',v_received,'due_now',v_due,'expected_not_due',v_expected,'future_conditional',v_cond,'remaining_to_receive',v_plan_total-v_received);
end;$function$;

create or replace function portal_private.trg_reconcile_finance_authority_from_signed_schedule_v8() returns trigger language plpgsql security definer set search_path to 'pg_catalog','portal_private' as $function$ begin if new.source_locked=true and coalesce(new.source_version,'') not like 'FINANCE_SIGNED_SCHEDULE_V8:%' then perform portal_private.reconcile_finance_authority_from_signed_schedule_v8(new.id); end if; return new; end;$function$;
drop trigger if exists finance_authority_signed_schedule_reconcile_v8 on portal_private.deal_finance_authority_v7;
create trigger finance_authority_signed_schedule_reconcile_v8 after insert on portal_private.deal_finance_authority_v7 for each row execute function portal_private.trg_reconcile_finance_authority_from_signed_schedule_v8();

create or replace function portal_private.persist_finance_signed_schedule_manifest_v8(p_job_id uuid) returns jsonb language plpgsql security definer set search_path to 'pg_catalog','portal_private' as $function$
declare j portal_private.finance_signed_schedule_jobs_v8%rowtype; d portal_private.documents%rowtype; dv portal_private.document_versions%rowtype; v_currency text; v_total numeric; v_version text; v_manifest jsonb; v_id uuid;
begin select * into j from portal_private.finance_signed_schedule_jobs_v8 where job_id=p_job_id; if not found or j.status<>'MATERIALIZED' or j.schedule_group_id is null then return jsonb_build_object('persisted',false,'reason_code','V8_JOB_NOT_MATERIALIZED'); end if; select * into d from portal_private.documents where id=j.source_document_key and deal_key=j.deal_key; if not found then return jsonb_build_object('persisted',false,'reason_code','SOURCE_DOCUMENT_NOT_FOUND'); end if; select * into dv from portal_private.document_versions where id=j.source_document_version_key and document_key=d.id; if not found or coalesce(dv.sha256,'')!~'^[0-9a-fA-F]{64}$' then return jsonb_build_object('persisted',false,'reason_code','SOURCE_DOCUMENT_VERSION_INVALID'); end if;
  select upper(trim(min(p.currency)::text)),sum(p.planned_amount),min(p.schedule_version),jsonb_build_object('schema','FINANCE_SIGNED_DOCUMENT_PAYMENT_SCHEDULE_V8','deal_id',(select deal_id from portal_private.deals where id=j.deal_key),'source_document_id',d.document_id,'currency',upper(trim(min(p.currency)::text)),'total_to_receive',sum(p.planned_amount),'schedule_version',min(p.schedule_version),'tranches',jsonb_agg(jsonb_build_object('tranche_no',p.tranche_no,'amount',p.planned_amount,'due_state',p.due_state,'trigger_type',p.trigger_type,'trigger_state',p.trigger_state,'next_tranche_condition',p.next_tranche_condition) order by p.tranche_no)) into v_currency,v_total,v_version,v_manifest from portal_private.owner_payment_plan p where p.deal_key=j.deal_key and p.schedule_group_id=j.schedule_group_id and p.schedule_authority_state='CONFIRMED' and p.status<>'CANCELLED'; if v_manifest is null or v_total is null or v_currency!~'^[A-Z]{3}$' then return jsonb_build_object('persisted',false,'reason_code','V8_ACTIVE_SCHEDULE_NOT_FOUND'); end if;
  insert into portal_private.finance_document_schedule_manifests_v8(deal_key,source_document_key,source_document_version_key,source_document_id,source_sha256,schedule_group_id,schedule_version,currency,total_to_receive,manifest,origin,authority_state,lifecycle_state,source_refs) values(j.deal_key,d.id,dv.id,d.document_id,lower(dv.sha256),j.schedule_group_id,v_version,v_currency::char(3),v_total,v_manifest,'FINANCE_MATERIALIZED_SIGNED_DOCUMENT','AUTHORITATIVE','CURRENT',jsonb_build_array(jsonb_build_object('source_type','DOCUMENT','source_id',d.document_id),jsonb_build_object('source_type','DOCUMENT_VERSION','source_id',dv.id::text),jsonb_build_object('source_type','PAYMENT_SCHEDULE','source_id',j.schedule_group_id::text),jsonb_build_object('source_type','BUSINESS_CHANGE_PROPOSAL','source_id',j.proposal_record_id::text),jsonb_build_object('source_type','OPERATIONS_DECISION','source_id',j.approval_record_id::text))) on conflict(source_document_version_key) do update set schedule_group_id=excluded.schedule_group_id,schedule_version=excluded.schedule_version,currency=excluded.currency,total_to_receive=excluded.total_to_receive,manifest=excluded.manifest,source_refs=excluded.source_refs,authority_state='AUTHORITATIVE',lifecycle_state='CURRENT',updated_at=clock_timestamp() returning manifest_id into v_id; return jsonb_build_object('persisted',true,'manifest_id',v_id,'document_id',d.document_id,'schedule_group_id',j.schedule_group_id);
end;$function$;

create or replace function portal_private.trg_persist_finance_signed_schedule_manifest_v8() returns trigger language plpgsql security definer set search_path to 'pg_catalog','portal_private' as $function$ begin if new.status='MATERIALIZED' and (tg_op='INSERT' or old.status is distinct from new.status or old.schedule_group_id is distinct from new.schedule_group_id) then perform portal_private.persist_finance_signed_schedule_manifest_v8(new.job_id); end if; return new; end;$function$;
drop trigger if exists finance_signed_schedule_manifest_cache_v8 on portal_private.finance_signed_schedule_jobs_v8;
create trigger finance_signed_schedule_manifest_cache_v8 after insert or update of status,schedule_group_id on portal_private.finance_signed_schedule_jobs_v8 for each row execute function portal_private.trg_persist_finance_signed_schedule_manifest_v8();

create or replace function portal_private.requeue_finance_v8_transient_ai_failure() returns trigger language plpgsql security definer set search_path to 'pg_catalog','portal_private' as $function$
declare v_n int; v_delay interval; v_ok boolean:=false; begin if new.source_type<>'STAFF_TASK' or new.source_id not like 'TASK-FIN-SCHEDULE-V8-%' or new.target_role::text<>'FINANCE' or new.state not in ('DELIVERED','DEAD_LETTER') then return new; end if; v_ok:=coalesce(new.last_error_code,'') in ('GROQ_HTTP_408','GROQ_HTTP_409','GROQ_HTTP_429','GROQ_HTTP_500','GROQ_HTTP_502','GROQ_HTTP_503','GROQ_HTTP_504','MODEL_PROVIDER_RATE_LIMIT','MODEL_PROVIDER_TIMEOUT','MODEL_PROVIDER_UNAVAILABLE','CURRENT_STATE_READ_FAILED','AI_TOKEN_NOT_YET_VALID','MODEL_OUTPUT_EMPTY','MODEL_OUTPUT_INVALID_JSON') or (coalesce(new.last_error_code,'')='RPC_RONA_AI_EXECUTOR_COMMIT_ACTION_FAILED' and coalesce(new.last_error_text,'')='AI_EXECUTOR_ENTITY_BINDING_MISMATCH'); if not v_ok then return new; end if; v_n:=coalesce(nullif(new.payload->>'v8_transient_recovery_count','')::int,0); if v_n>=12 then insert into portal_private.finance_schedule_integrity_alerts_v8(deal_key,reason_code,details,status) select st.deal_key,'FINANCE_AI_TRANSIENT_RETRY_EXHAUSTED',jsonb_build_object('task_id',new.source_id,'queue_id',new.id,'last_error_code',new.last_error_code,'last_error_text',left(coalesce(new.last_error_text,''),500),'recovery_count',v_n),'OPEN' from portal_private.staff_tasks st where st.task_id=new.source_id on conflict(deal_key,reason_code) where status='OPEN' do update set details=excluded.details,created_at=clock_timestamp(); return new; end if; v_delay:=make_interval(mins=>least(60,5*(2^least(v_n,3))::int)); update portal_private.ai_runtime_queue set state='QUEUED',attempts=0,available_at=clock_timestamp()+v_delay,deadline_at=clock_timestamp()+v_delay+interval '2 hours',lease_until=null,claimed_by=null,processed_at=null,last_error_code=null,last_error_text=null,payload=coalesce(payload,'{}'::jsonb)||jsonb_build_object('v8_transient_recovery_count',v_n+1,'v8_last_transient_error',new.last_error_code,'v8_last_transient_error_text',left(coalesce(new.last_error_text,''),500),'v8_requeued_at',clock_timestamp()),updated_at=clock_timestamp() where id=new.id; return new; end;$function$;
drop trigger if exists finance_v8_transient_ai_runtime_recovery on portal_private.ai_runtime_queue;
create trigger finance_v8_transient_ai_runtime_recovery after update of state,last_error_code on portal_private.ai_runtime_queue for each row when (new.state in ('DELIVERED','DEAD_LETTER') and new.last_error_code is not null) execute function portal_private.requeue_finance_v8_transient_ai_failure();

create or replace function portal_private.recover_finance_v8_stale_executor_queue_v1() returns jsonb language plpgsql security definer set search_path to 'pg_catalog','portal_private' as $function$
declare v_max int:=3; v_count int:=0; begin select coalesce(max_attempts,3) into v_max from portal_private.ai_model_executor_control where singleton=true; with c as (select q.id from portal_private.ai_runtime_queue q join portal_private.finance_signed_schedule_jobs_v8 j on j.staff_task_id=q.source_id where q.source_type='STAFF_TASK' and q.target_role::text='FINANCE' and q.source_id like 'TASK-FIN-SCHEDULE-V8-%' and j.status in ('PENDING_FINANCE','RETRY') and ((q.state='DELIVERED' and (q.lease_until is null or q.lease_until<clock_timestamp()) and q.attempts>=v_max) or (q.state='DELIVERED' and q.claimed_by is not null and q.lease_until<clock_timestamp()) or (q.state='PROCESSED' and j.proposal_record_id is null)) and coalesce(nullif(q.payload->>'v8_stale_recovery_count','')::int,0)<12 for update of q skip locked), u as (update portal_private.ai_runtime_queue q set state='DELIVERED',attempts=0,available_at=clock_timestamp(),lease_until=null,claimed_by=null,processed_at=null,last_error_code=null,last_error_text=null,payload=coalesce(q.payload,'{}'::jsonb)||jsonb_build_object('v8_stale_recovery_count',coalesce(nullif(q.payload->>'v8_stale_recovery_count','')::int,0)+1,'v8_stale_recovered_at',clock_timestamp()),updated_at=clock_timestamp() from c where q.id=c.id returning q.id) select count(*) into v_count from u; return jsonb_build_object('ok',true,'recovered',v_count,'at',clock_timestamp()); end;$function$;

create or replace function portal_private.run_finance_signed_schedule_watchdog_v8() returns jsonb language plpgsql security definer set search_path to 'pg_catalog','portal_private' as $function$
declare r record; v_job uuid; v_ensured int:=0; v_res jsonb; v_reconciled int:=0; begin for r in select distinct d.id document_key,d.current_version_id version_key from portal_private.documents d join portal_private.owner_deal_documents odd on odd.document_key=d.id join portal_private.deals x on x.id=odd.deal_key join portal_private.document_versions dv on dv.id=d.current_version_id and dv.document_key=d.id where upper(d.document_type) in ('SIGNED_ADDENDUM','SIGNED_SPECIFICATION','SIGNED_CONTRACT') and upper(d.authority_state::text)='CONFIRMED' and upper(d.lifecycle_state::text)='ACTIVE' and dv.is_current=true and dv.is_effective=true and upper(dv.authority_state::text)='CONFIRMED' and upper(dv.lifecycle_state::text)='ACTIVE' and upper(x.lifecycle_state::text)='ACTIVE' loop v_job:=portal_private.ensure_signed_document_schedule_job_v8(r.document_key,r.version_key); if v_job is not null then v_ensured:=v_ensured+1; end if; end loop; update portal_private.finance_signed_schedule_jobs_v8 j set status='SUPERSEDED',updated_at=clock_timestamp(),last_error='SOURCE_SIGNED_DOCUMENT_SUPERSEDED' where j.status<>'SUPERSEDED' and not exists(select 1 from portal_private.documents d join portal_private.document_versions dv on dv.id=d.current_version_id and dv.document_key=d.id where d.id=j.source_document_key and dv.id=j.source_document_version_key and upper(d.authority_state::text)='CONFIRMED' and upper(d.lifecycle_state::text)='ACTIVE' and dv.is_current=true and dv.is_effective=true and upper(dv.authority_state::text)='CONFIRMED' and upper(dv.lifecycle_state::text)='ACTIVE'); perform portal_private.recover_finance_v8_stale_executor_queue_v1(); for r in select a.id from portal_private.deal_finance_authority_v7 a where a.source_locked=true and upper(a.authority_state) not in ('SUPERSEDED','REJECTED','REVERSED','INVALID','INACTIVE') and upper(a.lifecycle_state) not in ('SUPERSEDED','REJECTED','REVERSED','ARCHIVED','INACTIVE') and not exists(select 1 from portal_private.deal_finance_authority_v7 n where n.supersedes_id=a.id and n.source_locked=true and upper(n.authority_state) not in ('SUPERSEDED','REJECTED','REVERSED','INVALID','INACTIVE') and upper(n.lifecycle_state) not in ('SUPERSEDED','REJECTED','REVERSED','ARCHIVED','INACTIVE')) and exists(select 1 from portal_private.owner_payment_plan p where p.deal_key=a.deal_key and p.schedule_authority_state='CONFIRMED' and p.status<>'CANCELLED' and p.source_system='FINANCE_SIGNED_DOCUMENT_PAYMENT_SCHEDULE_V8') loop v_res:=portal_private.reconcile_finance_authority_from_signed_schedule_v8(r.id); if coalesce((v_res->>'materialized')::boolean,false) then v_reconciled:=v_reconciled+1; end if; end loop; update portal_private.finance_schedule_integrity_alerts_v8 a set status='RESOLVED',resolved_at=clock_timestamp() where a.status='OPEN' and a.reason_code='FINANCE_V8_JOB_PENDING' and exists(select 1 from portal_private.finance_signed_schedule_jobs_v8 j where j.deal_key=a.deal_key and j.status='MATERIALIZED'); return jsonb_build_object('ok',true,'jobs_ensured',v_ensured,'authorities_reconciled',v_reconciled,'at',clock_timestamp()); end;$function$;

do $do$ begin if not exists(select 1 from cron.job where jobname='payments-v8-signed-schedule-watchdog') then perform cron.schedule('payments-v8-signed-schedule-watchdog','*/5 * * * *','select portal_private.run_finance_signed_schedule_watchdog_v8();'); end if; if not exists(select 1 from cron.job where jobname='payments-v8-stale-executor-recovery') then perform cron.schedule('payments-v8-stale-executor-recovery','*/2 * * * *','select portal_private.recover_finance_v8_stale_executor_queue_v1();'); end if; end;$do$;
